import React, { useState, useEffect, useCallback } from 'react';
import styles from './TerminalCursor.module.css';

// Seasonal character sets
const SEASONAL_CHARS = {
  spring: ['🌸', '🌷', '🌿', '🍃', '✨', '🌱', '💮', '🌼', '🐣', '🌈', '☔', '🍀'],
  summer: ['☀️', '🌊', '⛱️', '🍉', '🌺', '🔥', '⚡', '🌴', '🍦', '🐚', '🌻', '⭐'],
  autumn: ['🍂', '🍁', '🌙', '🎃', '🍎', '🌰', '🍄', '🕸️', '🦊', '🌾', '🍊', '🕯️'],
  winter: ['❄️', '⭐', '✨', '💠', '☃️', '🎄', '🔔', '🕯️', '🧣', '🌨️', '🎁', '🕊️'],
  cyberpunk: ['0', '1', '$', '#', '@', '&', '%', '>', '<', '/', '\\', '█', '▒', '▓'],
  retro: ['◢', '◣', '◤', '◥', '◆', '◇', '○', '●', '▰', '▱', '★', '♫', '☠'],
  nature: ['🌲', '🌳', '🌿', '🍃', '🍂', '🍁', '🌊', '⛰️', '🦋', '🐝', '🍄', '🌙'],
  galaxy: ['🌙', '⭐', '✨', '🌠', '🪐', '🌌', '☄️', '💫', '✨', '🌟', '⚡', '🌀']
};

// Color palettes for each mood
const COLOR_PALETTES = {
  spring: {
    primary: '#ff6b9d',
    secondary: '#c084fc',
    glow: '#f472b6',
    fallback: '#ff69b4'
  },
  summer: {
    primary: '#ff8c00',
    secondary: '#ff4757',
    glow: '#ff6347',
    fallback: '#ff6b35'
  },
  autumn: {
    primary: '#e67e22',
    secondary: '#d35400',
    glow: '#f39c12',
    fallback: '#e67e22'
  },
  winter: {
    primary: '#60a5fa',
    secondary: '#818cf8',
    glow: '#93c5fd',
    fallback: '#3b82f6'
  },
  cyberpunk: {
    primary: '#00ffcc',
    secondary: '#ff00ff',
    glow: '#00ffff',
    fallback: '#0ff'
  },
  retro: {
    primary: '#ffd700',
    secondary: '#ff6b35',
    glow: '#ffa500',
    fallback: '#ffcc00'
  },
  nature: {
    primary: '#10b981',
    secondary: '#34d399',
    glow: '#6ee7b7',
    fallback: '#22c55e'
  },
  galaxy: {
    primary: '#a855f7',
    secondary: '#ec4899',
    glow: '#d946ef',
    fallback: '#c084fc'
  }
};

const TerminalCursor = () => {
  const [particles, setParticles] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const [currentMood, setCurrentMood] = useState('cyberpunk'); // Default mood

  // Get random char based on current mood
  const getRandomChar = useCallback(() => {
    const chars = SEASONAL_CHARS[currentMood] || SEASONAL_CHARS.cyberpunk;
    return chars[Math.floor(Math.random() * chars.length)];
  }, [currentMood]);

  // Get random color variation based on mood
  const getColorStyle = useCallback(() => {
    const palette = COLOR_PALETTES[currentMood] || COLOR_PALETTES.cyberpunk;
    const colors = [palette.primary, palette.secondary, palette.glow];
    return colors[Math.floor(Math.random() * colors.length)];
  }, [currentMood]);

  const addParticle = useCallback((x, y) => {
    const id = Date.now() + Math.random();
    const char = getRandomChar();
    const color = getColorStyle();
    
    setParticles(prev => [...prev, { id, x, y, char, color }]);
    
    // Longer duration for decorative chars (emoji)
    const duration = char.length > 1 ? 1200 : 800;
    
    setTimeout(() => {
      setParticles(prev => prev.filter(p => p.id !== id));
    }, duration);
  }, [getRandomChar, getColorStyle]);

  // Change mood automatically based on date (optional)
  useEffect(() => {
    const getMoodByDate = () => {
      const month = new Date().getMonth();
      // Northern hemisphere seasons (adjust as needed)
      if (month >= 2 && month <= 4) return 'spring';      // Mar-May
      if (month >= 5 && month <= 7) return 'summer';      // Jun-Aug
      if (month >= 8 && month <= 10) return 'autumn';     // Sep-Nov
      return 'winter';                                     // Dec-Feb
    };
    
    // Uncomment to auto-set by season:
    // setCurrentMood(getMoodByDate());
    
    // Or cycle through moods every 30 seconds for demo
    const moods = ['spring', 'summer', 'autumn', 'winter', 'cyberpunk', 'retro', 'nature', 'galaxy'];
    let index = 0;
    const interval = setInterval(() => {
      index = (index + 1) % moods.length;
      setCurrentMood(moods[index]);
    }, 30000); // Change mood every 30 seconds
    
    return () => clearInterval(interval);
  }, []);

  // Mouse/Touch handling
  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    let lastMove = 0;
    let throttle = currentMood === 'winter' ? 80 : 50; // Winter slower, summer faster
    
    const handleMouseMove = (e) => {
      const now = Date.now();
      if (now - lastMove > throttle) {
        addParticle(e.clientX, e.clientY);
        lastMove = now;
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [addParticle, currentMood]);

  // Manual mood control (expose to window for console testing)
  useEffect(() => {
    window.__setTerminalMood = setCurrentMood;
    return () => { delete window.__setTerminalMood; };
  }, []);

  if (isTouchDevice) return null;

  return (
    <>
      {particles.map(p => (
        <span
          key={p.id}
          className={`${styles.matrixChar} ${styles[currentMood]}`}
          style={{
            left: `${p.x}px`,
            top: `${p.y}px`,
            color: p.color,
            textShadow: `0 0 8px ${p.color}, 0 0 15px ${p.color}80`,
          }}
        >
          {p.char}
        </span>
      ))}
    </>
  );
};

export default TerminalCursor;
